INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14701, 'Psalms 106:38', 'Psalms', 106, 38, '&nbsp;دوئ بې‌ګناه وينې توئ کړې د خپلو لوڼو او زامنو وينې يې توئ کړې، کوم چې د کنعان بُتانو ته دوئ قربانى کړل، د هغوئ د وينې په وجه هغه مُلک ناپاک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14702, 'Psalms 106:39', 'Psalms', 106, 39, '&nbsp;په خپلو بدو کارونو يې ځان پليت کړُو، په خپل دې عمل يې ځانونه زناکار کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14703, 'Psalms 106:40', 'Psalms', 106, 40, '&nbsp;نو په دې وجه مالِک خُدائ خپلو خلقو ته غصه شو او د خپلو خلقو نه بېزاره شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14704, 'Psalms 106:41', 'Psalms', 106, 41, '&nbsp;هغۀ دوئ نورو قومونو ته حواله کړل، او د هغوئ دشمنانو په دوئ باندې حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14705, 'Psalms 106:42', 'Psalms', 106, 42, '&nbsp;او دشمنانو په هغوئ باندې ظلم وکړو او د هغوئ زور طاقت ته يې حواله کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14706, 'Psalms 106:43', 'Psalms', 106, 43, '&nbsp;هغۀ څو څو ځلې دوئ بچ کړل، خو هغوئ سرکشى خوښه کړه او په خپله ګناه کښې مختورن شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14707, 'Psalms 106:44', 'Psalms', 106, 44, '&nbsp;خو هغۀ د هغوئ مصيبت ته پام شو کله چې هغۀ د هغوئ ژړا واورېده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14708, 'Psalms 106:45', 'Psalms', 106, 45, '&nbsp;د دوئ د خاطره هغۀ خپل لوظ ځان ته راياد کړو او هغۀ خپله فېصله د ابدى مينې په سبب بدله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14709, 'Psalms 106:46', 'Psalms', 106, 46, '&nbsp;په هغوئ يې هغه خلق مهربان کړل چا چې دوئ ګېر کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14710, 'Psalms 106:47', 'Psalms', 106, 47, '&nbsp;اے مالِکه خُدايه، زمونږ پاکه خُدايه مونږ بچ کړه، او مونږ د قومونو نه راغونډ کړه، نو چې دغه شان مونږ ستا د مقدس نوم شُکر ادا کړُو او ستا په جلال کښې ستا ثناء صِفت ادا کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14711, 'Psalms 106:48', 'Psalms', 106, 48, '&nbsp;د مالِک خُدائ ثناء صِفت دې وى څوک چې د بنى اِسرائيلو خُدائ پاک دے، د ازل نه تر ابده پورې دې د مالِک خُدائ ثناء صِفت وى. راځئ چې ټول په شريکه سره ووايو، ”آمين.“ ثناء صِفت دې مالِک خُدائ ته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14712, 'Psalms 107:1', 'Psalms', 107, 1, '&nbsp;د مالِک خُدائ شُکر کوئ، ځکه چې هغه ډېر ښۀ دے، او د هغۀ مينه تر ابده ‎پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14713, 'Psalms 107:2', 'Psalms', 107, 2, '&nbsp;چا ته چې مالِک خُدائ خلاصون ورکړى هغوئ دې خلقو ته ووائى، هغوئ هم څوک چې هغۀ د دشمن د لاس نه خلاص کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14714, 'Psalms 107:3', 'Psalms', 107, 3, '&nbsp;هغوئ هم چې هغۀ د مُلکونو نه راغونډ کړل، د مشرق او مغرب او د شمال او جنوب نه يې راغونډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14715, 'Psalms 107:4', 'Psalms', 107, 4, '&nbsp;په هغوئ کښې ځينې په خوشى بيابان کښې سرګردانه ګرځېدل، او د خپل ځان دپاره يې د اوسېدلو ښار پېدا نۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14716, 'Psalms 107:5', 'Psalms', 107, 5, '&nbsp;هغوئ اوږى تږى وُو، او مرګ ته نزدې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14717, 'Psalms 107:6', 'Psalms', 107, 6, '&nbsp;نو بيا هغوئ په خپلو سختو کښې مالِک خُدائ ته ژړا وکړه، هغۀ بيا هغوئ د مصيبت نه خلاص کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14718, 'Psalms 107:7', 'Psalms', 107, 7, '&nbsp;هغۀ هغوئ ته نېغه لاره وښودله ترڅو چې هغوئ د اوسېدلو دپاره هغه ښار پېدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14719, 'Psalms 107:8', 'Psalms', 107, 8, '&nbsp;نو د مالِک خُدائ شُکر دې د هغۀ د نۀ ختمېدونکې مينې دپاره ادا کړى او د هغۀ عجيبه کارونه چې د بنيادمو دپاره يې کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14720, 'Psalms 107:9', 'Psalms', 107, 9, '&nbsp;هغه تږو له تنده ماتوى او اوږى په ښۀ خوراکونو مړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14721, 'Psalms 107:10', 'Psalms', 107, 10, '&nbsp;په دوئ کښې څۀ په مصيبت او په زنځيرونو کښې پراتۀ وُو، قېديان په کښې په زنځيرونو کښې پراتۀ وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14722, 'Psalms 107:11', 'Psalms', 107, 11, '&nbsp;هغوئ د خُدائ د کلام مخالفت کړے وو او هغوئ د خُدائ تعالىٰ د مشورې سپکاوے کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14723, 'Psalms 107:12', 'Psalms', 107, 12, '&nbsp;هغۀ هغوئ په سخت تکليف کښې واچول، هغوئ تيندکونه خوړل خو مدد يې چا هم نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14724, 'Psalms 107:13', 'Psalms', 107, 13, '&nbsp;نو بيا هغوئ په سخته کښې مالِک خُدائ ته ژړا وکړه، او هغۀ هغوئ د مصيبت نه خلاص کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14725, 'Psalms 107:14', 'Psalms', 107, 14, '&nbsp;او هغۀ هغوئ د تيارې نه بهر راوويستل او د هغوئ زنځيرونه يې مات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14726, 'Psalms 107:15', 'Psalms', 107, 15, '&nbsp;نو د مالِک خُدائ شُکر دې د هغۀ د نۀ ختمېدونکې مينې دپاره ادا کړى او د هغۀ عجيبه کارونه چې د بنيادمو دپاره يې کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14727, 'Psalms 107:16', 'Psalms', 107, 16, '&nbsp;ځکه چې هغۀ د زېړو دروازې ماتې کړې او د هغې د اوسپنو سيخونه يې غوڅ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14728, 'Psalms 107:17', 'Psalms', 107, 17, '&nbsp;نو څۀ خلق د خپلو بدعملو په وجه کم عقل شول او د خپلو خطاګانو په وجه په مصيبت کښې ګېر شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14729, 'Psalms 107:18', 'Psalms', 107, 18, '&nbsp;او د هر قسمه خوراکونو نه بېزاره وُو او د مرګ دروازې ته نزدې شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14730, 'Psalms 107:19', 'Psalms', 107, 19, '&nbsp;نو بيا هغوئ په سخته کښې مالِک خُدائ ته ژړا وکړه، او هغوئ يې د مصيبت نه خلاص کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14731, 'Psalms 107:20', 'Psalms', 107, 20, '&nbsp;او هغۀ خپل کلام ورولېږلو او هغوئ يې روغ کړل، او د قبر نه يې ورله خلاصون ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14732, 'Psalms 107:21', 'Psalms', 107, 21, '&nbsp;نو د مالِک خُدائ شُکر دې د هغۀ د نۀ ختمېدونکې مينې دپاره ادا کړى او د هغه عجيبه کارونو دپاره چې د بنيادمو دپاره يې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14733, 'Psalms 107:22', 'Psalms', 107, 22, '&nbsp;هغوئ دې مالِک خُدائ ته د شُکر ګزارۍ قربانى وړاندې کړى او د هغۀ کارونه دې د خوښۍ په سندرو کښې بيان کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14734, 'Psalms 107:23', 'Psalms', 107, 23, '&nbsp;او څۀ خلق په سمندرى بيړو کښې په سمندر کښې لاړل، او هغوئ په زورَورو اوبو کښې تجارت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14735, 'Psalms 107:24', 'Psalms', 107, 24, '&nbsp;هغوئ د مالِک خُدائ کارونه وليدل، او د هغۀ عجيبه کارونه يې په ډوبو ځايونو کښې وليدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14736, 'Psalms 107:25', 'Psalms', 107, 25, '&nbsp;هغۀ کلام وکړو نو تېز طوفان راغلو او د سمندر چپې اوچتې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14737, 'Psalms 107:26', 'Psalms', 107, 26, '&nbsp;هغوئ به کله آسمان ته ختل او کله به لاندې د اوبو بېخ ته تلل، نو په دې سخت طوفان کښې هغوئ همت بائيللو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14738, 'Psalms 107:27', 'Psalms', 107, 27, '&nbsp;د نشيانو په شان په ټوپونو او تيندکونو باندې سر وُو، او دوئ نه په آخر کښې يو دوه خطا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14739, 'Psalms 107:28', 'Psalms', 107, 28, '&nbsp;نو بيا هغوئ په سخته کښې مالِک خُدائ ته فرياد وکړو، او هغوئ ته يې د مصيبت نه خلاصون ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14740, 'Psalms 107:29', 'Psalms', 107, 29, '&nbsp;هغۀ طوفان په قلاره کړو، او د سمندر چپې او موجونه په آرام شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14741, 'Psalms 107:30', 'Psalms', 107, 30, '&nbsp;نو کله چې هغه طوفان قلار شو نو دوئ خوشحاله شول، څۀ چې دوئ غوښتل نو تر هغه غاړې يې راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14742, 'Psalms 107:31', 'Psalms', 107, 31, '&nbsp;نو د مالِک خُدائ شُکر دې د هغۀ د نۀ ختمېدونکې مينې دپاره ادا کړى او د هغه عجيبه کارونو دپاره چې د بنيادمو دپاره يې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14743, 'Psalms 107:32', 'Psalms', 107, 32, '&nbsp;د خلقو په ډله کښې دې د خُدائ پاک لوئ بيانوى او د مشرانو په محفل کښې دې د هغۀ ثناء صِفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14744, 'Psalms 107:33', 'Psalms', 107, 33, '&nbsp;هغۀ دريابونه په بيابان بدل کړل، او د اوبو چينې يې په اوچه زمکه بدلې کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14745, 'Psalms 107:34', 'Psalms', 107, 34, '&nbsp;زرخيزه زمکه يې په مالګينه زمکه بدله کړه، د هغوئ د بدو عملونو په وجه څوک چې هلته په کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14746, 'Psalms 107:35', 'Psalms', 107, 35, '&nbsp;او هغۀ بيابانونه د اوبو په تالابونو باندې بدل کړل او اوچه زمکه يې د اوبو په چينو بدله کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14747, 'Psalms 107:36', 'Psalms', 107, 36, '&nbsp;هغۀ هلته اوږى د اوسېدلو دپاره ولېږل، او هغوئ هلته د اوسېدو دپاره د ښار بنيادونه کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14748, 'Psalms 107:37', 'Psalms', 107, 37, '&nbsp;او هلته هغوئ کرونده او د انګورو باغونه شروع کړل چې هغې هغوئ ته ډېر پېداوار ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14749, 'Psalms 107:38', 'Psalms', 107, 38, '&nbsp;هغۀ هغوئ ته برکت ورکړو او شمېر يې ورله ډېر زيات کړو، او هغۀ د هغوئ په رمو کښې نقصان رانۀ وستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14750, 'Psalms 107:39', 'Psalms', 107, 39, '&nbsp;او بيا يې شمېر په کمېدو شو او عاجزان شول د ظلم، مصيبت او خفګان په وجه خوار و زار شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14751, 'Psalms 107:40', 'Psalms', 107, 40, '&nbsp;مالِک خُدائ په خپله شهزادګان سپکوى هغه هغوئ په خوشى دشتو کښې سرګردانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14752, 'Psalms 107:41', 'Psalms', 107, 41, '&nbsp;خو هغۀ محتاجه د ظلمونو نه خلاص کړل او د هغوئ خاندان يې لکه د رمو په شان زيات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14753, 'Psalms 107:42', 'Psalms', 107, 42, '&nbsp;او صادقان دا ګورى او ورته خوشحالى کوى، او ټول بدعمله به خپلې خولې بندې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14754, 'Psalms 107:43', 'Psalms', 107, 43, '&nbsp;څوک چې هوښيار وى نو هغوئ دې په دې خبرو باندې غور وکړى، او د مالِک خُدائ په لويه مينه باندې دې غور وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14755, 'Psalms 108:1', 'Psalms', 108, 1, '&nbsp;اے مالِکه خُدايه، زما زړۀ په تا مضبوط دے، زۀ به په خپل ټول ځان سره ستا حمد او سرود وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14756, 'Psalms 108:2', 'Psalms', 108, 2, '&nbsp;اے سريندې او ربابه پاڅه، زۀ به په خپلو سندرو سره سحر راپاڅوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14757, 'Psalms 108:3', 'Psalms', 108, 3, '&nbsp;اے مالِکه خُدايه، زۀ به ستا ثناء په قومونو کښې بيان کړم، د خلقو مينځ کښې به دې حمدونه وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14758, 'Psalms 108:4', 'Psalms', 108, 4, '&nbsp;ځکه چې ستا ابدى مينه لويه او د آسمانونو دپاسه ده، او ستا وفادارى تر آسمانونو پورې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14759, 'Psalms 108:5', 'Psalms', 108, 5, '&nbsp;اے پاکه خُدايه، پاس په آسمانونو دې ستا لوئى وى، او ستا جلال دې د ټولې زمکې دپاسه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14760, 'Psalms 108:6', 'Psalms', 108, 6, '&nbsp;مونږ دې په خپل ښى لاس سره بچ کړه او زمونږ مدد وکړه، او د چا سره چې تۀ مينه کوې هغوئ بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14761, 'Psalms 108:7', 'Psalms', 108, 7, '&nbsp;خُدائ د خپل مقدس ځائ نه کلام وکړو، ”په خوشحالۍ سره به شِکم تقسيم کړم او د سُکات دره به ناپ تول کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14762, 'Psalms 108:8', 'Psalms', 108, 8, '&nbsp;جِلعاد زما دے او منسى هم زما دے، اِفرائيم زما ټوپۍ او يهوداه زما د بادشاهۍ کونټۍ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14763, 'Psalms 108:9', 'Psalms', 108, 9, '&nbsp;موآب زما د وينځلو ښانک دے او هغه به زما خِدمتګار وى، او زۀ په ادوم باندې خپلې څپلۍ پاکوم، او زۀ به په فلستيه مُلک باندې د کاميابۍ چغه وهم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14764, 'Psalms 108:10', 'Psalms', 108, 10, '&nbsp;ما به څوک د برجونو ښار ته راولى؟ څوک به ما ته په ادوم باندې کاميابى راکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14765, 'Psalms 108:11', 'Psalms', 108, 11, '&nbsp;اے پاکه خُدايه، مونږ تا رد کړى يُو څۀ زمونږ د لښکرو سره نور نۀ ځې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14766, 'Psalms 108:12', 'Psalms', 108, 12, '&nbsp;د دشمن خلاف زمونږ مدد وکړه، ځکه چې د بنى آدم امداد بې‌فائدې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14767, 'Psalms 108:13', 'Psalms', 108, 13, '&nbsp;د خُدائ پاک په مدد سره به مونږ ګټه وکړُو، او هغه به زمونږ دشمن چخڼى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14768, 'Psalms 109:1', 'Psalms', 109, 1, '&nbsp;اے پاکه خُدايه، د چا چې زۀ ثناء صِفت کوم، تۀ خاموشه مۀ پاتې کېږه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14769, 'Psalms 109:2', 'Psalms', 109, 2, '&nbsp;ځکه چې بدعملو او دوکه بازو زما خلاف خپله خولۀ خلاصه کړې ده، او دوئ زما په حقله دروغ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14770, 'Psalms 109:3', 'Psalms', 109, 3, '&nbsp;د نفرتونو ګېره يې زما نه راتاو کړې ده، دوئ هيڅ بې‌هيڅه په ما حمله کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14771, 'Psalms 109:4', 'Psalms', 109, 4, '&nbsp;زما د مينې په بدل کښې يې په ما اِلزامونه ولګول، خو زۀ د هغوئ دپاره دُعا کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14772, 'Psalms 109:5', 'Psalms', 109, 5, '&nbsp;زما د ښو په بدله کښې ما سره بد کوى، دوئ زما د مينې په بدله کښې ما نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14773, 'Psalms 109:6', 'Psalms', 109, 6, '&nbsp;اے خُدايه، تۀ په دوئ باندې خراب خلق مقرر کړه چې دوئ ملامته کړى، په دۀ اِلزام لګونکے دې د دۀ ښى لاس ته ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14774, 'Psalms 109:7', 'Psalms', 109, 7, '&nbsp;او هغه دې په عدالت کښې مجرم وګرځولے شى، او د هغۀ دُعاګانې دې ورته په ګناه حساب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14775, 'Psalms 109:8', 'Psalms', 109, 8, '&nbsp;او د هغۀ عُمر دې لنډ شى، د هغۀ د مشرۍ مقام دې نورو خلقو ته حواله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14776, 'Psalms 109:9', 'Psalms', 109, 9, '&nbsp;د هغۀ بچى دې يتيمانان شى د هغۀ ښځه دې کونډه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14777, 'Psalms 109:10', 'Psalms', 109, 10, '&nbsp;د هغۀ بچى دې ملنګان او خيرماران شى، او د خپلو ورانو کنډرو نه دې وويستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14778, 'Psalms 109:11', 'Psalms', 109, 11, '&nbsp;قرض‌خوا دې د هغۀ نه هر څۀ واخلى، او د هغۀ د مزدورۍ مېوه دې پردى خلق لوټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14779, 'Psalms 109:12', 'Psalms', 109, 12, '&nbsp;هغۀ سره دې څوک ښېګړه ونۀ کړى او نۀ دې څوک د هغۀ په يتيمانانو بچو رحم وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14780, 'Psalms 109:13', 'Psalms', 109, 13, '&nbsp;په دُنيا کښې دې د هغۀ نسل ختم شى، او په راتلونکى نسل کښې دې د هغۀ نوم ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14781, 'Psalms 109:14', 'Psalms', 109, 14, '&nbsp;مالِک خُدائ دې د هغۀ د پلار نيکۀ ګناهونه نۀ هېروى، او نۀ دې د هغۀ د مور ګناهونه وروبخښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14782, 'Psalms 109:15', 'Psalms', 109, 15, '&nbsp;او د هغوئ ګناهونه دې د تل دپاره د مالِک خُدائ په وړاندې وى، نو چې دغه شان د هغوئ يادګار د زمکې نه ورک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14783, 'Psalms 109:16', 'Psalms', 109, 16, '&nbsp;ځکه چې هغۀ کله په چا باندې د رحم کولو سوچ هم نۀ دے کړے، خو تل د غريب او حاجتمند او د مايوسه د مرګ بندوبست کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14784, 'Psalms 109:17', 'Psalms', 109, 17, '&nbsp;د هغۀ د لعنت کولو سره مينه وه خو دا دې په هم دۀ راواپس شى، د هغۀ برکت ورکول نۀ خوښېدل نو برکت دې هغۀ نه لرې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14785, 'Psalms 109:18', 'Psalms', 109, 18, '&nbsp;لعنت يې لکه د جامو اغوستے وو، دا د دۀ بدن ته لکه د اوبو ورننوتے وو، او هډوکو ته يې لکه د تېلو ورننوتے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14786, 'Psalms 109:19', 'Psalms', 109, 19, '&nbsp;د چُوغې په شان دې دا لعنت هم د دۀ نه راتاو شى، او د کمربند په شان دې د تل دپاره د ملا نه تاو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14787, 'Psalms 109:20', 'Psalms', 109, 20, '&nbsp;څوک چې په ما اِلزام لګوى هغوئ ته دې دغه سزا ورکړى، او هغوئ ته هم څوک چې زما غېبت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14788, 'Psalms 109:21', 'Psalms', 109, 21, '&nbsp;خو تۀ، اے قادر مطلق مالِکه خُدايه، د خپل نوم په خاطر دې هم ما سره ښۀ وکړه، او د خپلې مينې د ښۀ‌والى په خاطر دې هم ما بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14789, 'Psalms 109:22', 'Psalms', 109, 22, '&nbsp;ځکه چې زۀ غريب او ضرورتمند يم، او زړۀ په ما کښې دننه زخمى دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14790, 'Psalms 109:23', 'Psalms', 109, 23, '&nbsp;زۀ لکه د مازيګر د سورى په شان په ختمېدو يم، او زۀ لکه د مُلخ په شان شړلے شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14791, 'Psalms 109:24', 'Psalms', 109, 24, '&nbsp;زما ګوډې د روژو په وجه کمزورې شوې دى، او زما نه د هډوکو تشه ډانچه جوړه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14792, 'Psalms 109:25', 'Psalms', 109, 25, '&nbsp;زۀ د خپلو دشمنانو د خندا شوم، کله چې هم ما ګورى نو خپل سرونه خوځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14793, 'Psalms 109:26', 'Psalms', 109, 26, '&nbsp;اے مالِکه خُدايه، زما پاکه خُدايه ما سره مدد وکړه، د خپلې ابدى مينې په خاطر ما بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14794, 'Psalms 109:27', 'Psalms', 109, 27, '&nbsp;هغوئ ته دې معلومه شى چې دا ستا لاس وو، چې دا هر څۀ تا وکړل اے مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14795, 'Psalms 109:28', 'Psalms', 109, 28, '&nbsp;دوئ به لعنت کوى خو تۀ به برکت ورکوې، کله چې دوئ حمله وکړى نو تۀ به يې وشرموې، خو ستا خِدمتګار به خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14796, 'Psalms 109:29', 'Psalms', 109, 29, '&nbsp;په ما اِلزام لګونکى دې په شرم پټ شى شرم کښې دې د چُوغې په شان پټ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14797, 'Psalms 109:30', 'Psalms', 109, 30, '&nbsp;زۀ به په خپله ژبه د مالِک خُدائ لوئى بيان کړم، او زۀ به په لويه ډله کښې د هغۀ ثناء صِفت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14798, 'Psalms 109:31', 'Psalms', 109, 31, '&nbsp;ځکه چې هغه د حاجتمندو مددګار دے، چې د هغه چا نه يې وساتى څوک چې دوئ مجرموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14799, 'Psalms 110:1', 'Psalms', 110, 1, '&nbsp;مالِک زما مالِک ته وفرمائيل، ”زما ښى لاس ته کښېنه ترڅو چې زۀ ستا دشمنان ستا د پښو لاندې کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14800, 'Psalms 110:2', 'Psalms', 110, 2, '&nbsp;مالِک خُدائ به د صيون نه ستا زورَوره امسا راوغزوى، نو تۀ به په خپلو دشمنانو باندې حکومت کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');